const append = $json || {};
const tokenRes = $node['Google | Refresh Access Token'].json || {};
const row = $node['Tool | Normalize Call Log'].json?.row || {};

const tokenError = tokenRes.error || tokenRes.error_description || '';
const appendError = append.error?.message || append.error || '';
const ok = !tokenError && !appendError;

return [{
  ok,
  tool: 'call_log',
  source: ok ? 'google_sheets' : 'error',
  warning: ok ? '' : String(tokenError || appendError || 'Google append failed'),
  spreadsheet_id: $node['Google | Build Payload'].json?.spreadsheet_id || '',
  updated_range: append.updates?.updatedRange || '',
  updated_rows: append.updates?.updatedRows ?? 0,
  lead_id: row.lead_id || '',
  call_result: row.call_result || '',
  next_step: row.next_step || '',
  next_call_at: row.next_call_at || '',
}];
